    /**
     * Tests creating a new WealthFirm.
     *
     * @return    WealthFirm
     */
    public WealthFirm testCreate() throws Throwable {
    WealthFirm entity = null;

    LOGGER.info( "WealthFirmTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a WealthFirm");

    StringBuilder msg = new StringBuilder( "-- Failed to create a WealthFirm" );

    try {
        entity = service.createWealthFirm( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getWealthFirmId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a WealthFirm with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

