    /**
     * Tests getting all WealthFirms.
     *
     * @return    Collection
     */
    public List<WealthFirm> testGetAll() throws Throwable {
    LOGGER.info( "WealthFirmTest:testGetAll() - Retrieving Collection of WealthFirms:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all WealthFirm : " );
    List<WealthFirm> collection  = null;

    try {
        // call the static get method on the WealthFirmService
        collection = service.getAllWealthFirm();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            WealthFirm currEntity  = null;
            Iterator<WealthFirm> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getWealthFirmId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

